def normalize(value):
    return " ".join(str(value).strip().lower().split())

def inspect_sheet(ws):
    """Return the best header row and semantic-to-column mapping."""
    best = None

    for row_number in range(1, min(ws.max_row, 30) + 1):
        normalized_headers = {
            normalize(cell.value): cell.column
            for cell in ws[row_number]
            if cell.value is not None
        }

        mapping = {}
        for field, aliases in header_aliases.items():
            for alias in aliases:
                if alias in normalized_headers:
                    mapping[field] = normalized_headers[alias]
                    break

        score = len(mapping)
        if "flight" in mapping:
            score += 3
        if "date" in mapping:
            score += 2

        candidate = (score, row_number, mapping)
        if best is None or candidate[0] > best[0]:
            best = candidate

    return best

